{
  "type": "statechart",
  "id": "_verify_fs_path_statechart",
  "initial": "getting_flow_dir",
  "context": {
    "flow_id": "UUID",
    "flow_dir": "Path object"
  },
  "states": {
    "getting_flow_dir": {
      "entry": "get_flow_dir_path",
      "description": "FLOWS_PATH / str(flow_id)",
      "on": {
        "PATH_OBTAINED": "checking_existence"
      }
    },
    "checking_existence": {
      "entry": "check_path_exists",
      "description": "flow_dir.exists()",
      "on": {
        "EXISTS": "complete",
        "NOT_EXISTS": "creating_directory"
      }
    },
    "creating_directory": {
      "entry": "create_directory",
      "description": "flow_dir.mkdir(parents=True, exist_ok=True)",
      "on": {
        "CREATED": "complete",
        "ERROR": "error_filesystem"
      }
    },
    "complete": {
      "type": "final",
      "data": {
        "flow_dir": "Path to flow directory"
      }
    },
    "error_filesystem": {
      "type": "final",
      "entry": "raise_exception",
      "data": {
        "error": "Failed to create directory"
      }
    }
  }
}

{
  "type": "statechart",
  "id": "_save_flow_to_fs_statechart",
  "initial": "verifying_path",
  "context": {
    "db_flow": "Flow object",
    "flow_dir": "Path object",
    "flow_data": "Flow dict"
  },
  "states": {
    "verifying_path": {
      "entry": "call_verify_fs_path",
      "description": "Calls _verify_fs_path(db_flow.id)",
      "on": {
        "PATH_VERIFIED": "serializing_flow",
        "ERROR": "error_filesystem"
      }
    },
    "serializing_flow": {
      "entry": "serialize_to_dict",
      "description": "db_flow.model_dump(exclude={'user_id'})",
      "on": {
        "SERIALIZED": "writing_json_file"
      }
    },
    "writing_json_file": {
      "entry": "write_json",
      "description": "(flow_dir / 'flow.json').write_text(json.dumps(flow_data, indent=2))",
      "on": {
