{
  "type": "statechart",
  "id": "_new_flow_statechart",
  "initial": "checking_unique_name",
  "context": {
    "flow": "Flow object",
    "user_id": "UUID",
    "session": "Database session",
    "existing_flow": "Query result"
  },
  "states": {
    "checking_unique_name": {
      "entry": "query_flow_by_name",
      "description": "SELECT * FROM flow WHERE name = flow.name AND user_id = user_id",
      "on": {
        "NAME_EXISTS": "generating_unique_name",
        "NAME_AVAILABLE": "checking_unique_endpoint"
      }
    },
    "generating_unique_name": {
      "entry": "query_numbered_flows",
      "description": "SELECT * FROM flow WHERE name LIKE '{name} (%)' AND user_id = user_id",
      "on": {
        "NUMBERS_FOUND": "appending_number",
        "NO_NUMBERS": "appending_first_number"
      }
    },
    "appending_number": {
      "entry": "append_max_plus_one",
      "description": "flow.name = f\"{flow.name} ({max(numbers) + 1})\"",
      "on": {
        "APPENDED": "checking_unique_endpoint"
      }
    },
    "appending_first_number": {
      "entry": "append_one",
      "description": "flow.name = f\"{flow.name} (1)\"",
      "on": {
        "APPENDED": "checking_unique_endpoint"
      }
    },
    "checking_unique_endpoint": {
      "entry": "query_flow_by_endpoint",
      "description": "SELECT * FROM flow WHERE endpoint_name = endpoint AND user_id = user_id",
      "on": {
        "ENDPOINT_EXISTS": "generating_unique_endpoint",
        "ENDPOINT_NULL": "resolving_folder",
        "ENDPOINT_AVAILABLE": "resolving_folder"
      }
    },
    "generating_unique_endpoint": {
      "entry": "append_uuid_to_endpoint",
      "description": "Appends short UUID to make endpoint unique",
      "on": {
        "GENERATED": "resolving_folder"
      }
    },
    "resolving_folder": {
      "entry": "check_folder_id",
      "on": {
        "FOLDER_PROVIDED": "creating_flow_object",
        "FOLDER_NULL": "getting_default_folder"
      }
    },
    "getting_default_folder": {
      "entry": "query_default_folder",
      "description": "SELECT * FROM folder WHERE name = 'My Projects' AND user_id = user_id",
      "on": {
        "FOUND": "assigning_folder",
        "NOT_FOUND": "error_no_default_folder"
      }
    },
    "assigning_folder": {
      "entry": "set_folder_id",
      "description": "flow.folder_id = default_folder.id",
      "on": {
        "ASSIGNED": "creating_flow_object"
      }
    },
    "creating_flow_object": {
      "entry": "instantiate_flow_model",
      "description": "Create Flow(**flow.model_dump(), user_id=user_id)",
      "on": {
        "CREATED": "adding_to_session"
      }
    },
    "adding_to_session": {
      "entry": "session_add",
      "description": "session.add(db_flow)",
      "on": {
        "ADDED": "complete"
      }
    },
    "complete": {
      "type": "final",
      "data": {
        "db_flow": "Flow object ready for commit"
      }
    },
    "error_no_default_folder": {
      "type": "final",
      "entry": "raise_http_500",
      "data": {
        "error": "Default folder 'My Projects' not found"
      }
    }
  }
}

