  "initial": "creating_memory_buffer",
  "context": {
    "flow_ids": "List[UUID]",
    "user_id": "UUID",
    "session": "Database session",
    "zip_buffer": "BytesIO buffer",
    "current_flow": "Flow being processed"
  },
  "states": {
    "creating_memory_buffer": {
      "entry": "create_bytes_io",
      "description": "BytesIO() for in-memory ZIP",
      "on": {
        "CREATED": "creating_zip_file"
      }
    },
    "creating_zip_file": {
      "entry": "create_zipfile",
      "description": "ZipFile(zip_buffer, 'w', ZIP_DEFLATED)",
      "on": {
        "CREATED": "iterating_flow_ids"
      }
    },
    "iterating_flow_ids": {
      "entry": "get_next_flow_id",
      "on": {
        "HAS_FLOW": "reading_flow",
        "NO_MORE_FLOWS": "closing_zip_file"
      }
    },
    "reading_flow": {
      "entry": "call_read_flow",
      "description": "Calls _read_flow(flow_id, session, user_id)",
      "on": {
        "FOUND": "serializing_flow",
        "NOT_FOUND": "iterating_flow_ids"
      }
    },
    "serializing_flow": {
      "entry": "serialize_to_json",
      "description": "json.dumps(flow.model_dump(), indent=2)",
      "on": {
        "SERIALIZED": "adding_to_zip"
      }
    },
    "adding_to_zip": {
      "entry": "write_to_zip",
      "description": "zipfile.writestr(f'{flow.name}.json', flow_json)",
      "on": {
        "ADDED": "iterating_flow_ids",
        "ERROR": "error_zip"
      }
    },
    "closing_zip_file": {
      "entry": "close_zip",
      "description": "zipfile.close()",
      "on": {
        "CLOSED": "seeking_buffer"
      }
    },
    "seeking_buffer": {
      "entry": "seek_to_start",
      "description": "zip_buffer.seek(0)",
      "on": {
        "SEEKED": "complete"
      }
    },
    "complete": {
      "type": "final",
      "data": {
        "response": "StreamingResponse with ZIP file"
      }
    },
    "error_zip": {
      "type": "final",
      "entry": "raise_http_500",
      "data": {
        "error": "Failed to create ZIP file"
      }
    }
  }
}

