{
  "type": "statechart",
  "id": "download_file_statechart",
  "initial": "reading_folder",
  "context": {
    "folder_id": "UUID",
    "user_id": "UUID",
    "session": "Database session",
    "zip_buffer": "BytesIO buffer"
  },
  "states": {
    "reading_folder": {
      "entry": "query_folder_by_id",
      "description": "SELECT * FROM folder WHERE id = folder_id AND user_id = user_id",
      "on": {
        "FOUND": "loading_flows",
        "NOT_FOUND": "error_not_found"
      }
    },
    "loading_flows": {
      "entry": "load_folder_flows",
      "description": "SELECT * FROM flow WHERE folder_id = folder_id",
      "on": {
        "FLOWS_FOUND": "creating_memory_buffer",
        "NO_FLOWS": "error_no_content"
      }
    },
    "creating_memory_buffer": {
      "entry": "create_bytes_io",
      "description": "BytesIO() for in-memory ZIP",
      "on": {
        "CREATED": "creating_zip_file"
      }
    },
    "creating_zip_file": {
      "entry": "create_zipfile",
      "description": "ZipFile(zip_buffer, 'w', ZIP_DEFLATED)",
      "on": {
        "CREATED": "iterating_flows"
      }
    },
    "iterating_flows": {
      "entry": "get_next_flow",
      "on": {
        "HAS_FLOW": "serializing_flow",
        "NO_MORE_FLOWS": "closing_zip_file"
      }
    },
    "serializing_flow": {
      "entry": "serialize_to_json",
      "description": "json.dumps(flow.model_dump(), indent=2)",
      "on": {
        "SERIALIZED": "adding_to_zip"
      }
    },
    "adding_to_zip": {
      "entry": "write_to_zip",
      "description": "zipfile.writestr(f'{flow.name}.json', flow_json)",
      "on": {
        "ADDED": "iterating_flows",
        "ERROR": "error_zip"
      }
    },
    "closing_zip_file": {
      "entry": "close_zip",
      "description": "zipfile.close()",
      "on": {
        "CLOSED": "seeking_buffer"
      }
    },
    "seeking_buffer": {
      "entry": "seek_to_start",
      "description": "zip_buffer.seek(0)",
      "on": {
        "SEEKED": "complete"
      }
    },
    "complete": {
      "type": "final",
      "data": {
        "response": "StreamingResponse with ZIP file of all flows in folder"
      }
    },
    "error_not_found": {
      "type": "final",
      "entry": "raise_http_404",
      "data": {
        "error": "Project (folder) not found"
      }
    },
    "error_no_content": {
      "type": "final",
      "entry": "raise_http_204",
      "data": {
        "message": "No flows in folder to download"
      }
    },
    "error_zip": {
      "type": "final",
      "entry": "raise_http_500",
      "data": {
        "error": "Failed to create ZIP file"
      }
    }
  }
}

