{
  "type": "statechart",
  "id": "update_variable_statechart",
  "initial": "reading_existing_variable",
  "context": {
    "variable_id": "UUID",
    "variable_update": "VariableUpdate object",
    "user_id": "UUID",
    "session": "Database session",
    "db_variable": "Existing variable object"
  },
  "states": {
    "reading_existing_variable": {
      "entry": "query_variable_by_id",
      "description": "SELECT * FROM variable WHERE id = variable_id AND user_id = user_id",
      "on": {
        "FOUND": "checking_value_update",
        "NOT_FOUND": "error_not_found"
      }
    },
    "checking_value_update": {
      "entry": "check_value_field",
      "description": "Check if variable_update.value is set",
      "on": {
        "VALUE_PROVIDED": "encrypting_new_value",
        "NO_VALUE": "updating_fields"
      }
    },
    "encrypting_new_value": {
      "entry": "encrypt_with_fernet",
      "description": "Uses Fernet symmetric encryption",
      "on": {
        "ENCRYPTED": "updating_fields_with_value"
      }
    },
    "updating_fields_with_value": {
      "entry": "update_variable_fields",
      "description": "Update fields including encrypted value",
      "on": {
        "UPDATED": "adding_to_session"
      }
    },
    "updating_fields": {
      "entry": "update_variable_fields",
      "description": "Update fields from variable_update.model_dump(exclude_unset=True)",
      "on": {
        "UPDATED": "adding_to_session"
      }
    },
    "adding_to_session": {
      "entry": "session_add",
      "description": "session.add(db_variable)",
      "on": {
        "ADDED": "committing_transaction"
      }
    },
    "committing_transaction": {
      "entry": "session_commit",
      "description": "await session.commit()",
      "on": {
        "COMMITTED": "refreshing_variable",
        "INTEGRITY_ERROR": "error_database_constraint",
        "ERROR": "error_database"
      }
    },
    "refreshing_variable": {
      "entry": "session_refresh",
      "description": "await session.refresh(db_variable)",
      "on": {
        "REFRESHED": "decrypting_value"
      }
    },
    "decrypting_value": {
      "entry": "decrypt_with_fernet",
      "description": "Decrypt value before returning to client",
      "on": {
        "DECRYPTED": "complete"
      }
    },
    "complete": {
      "type": "final",
      "data": {
        "variable": "Updated VariableRead object (value decrypted)"
      }
    },
    "error_not_found": {
      "type": "final",
      "entry": "raise_http_404",
      "data": {
        "error": "Variable not found"
      }
    },
    "error_database_constraint": {
      "type": "final",
      "entry": "raise_http_409",
      "data": {
        "error": "Variable name must be unique for user"
      }
    },
    "error_database": {
      "type": "final",
      "entry": "raise_http_500",
      "data": {
        "error": "Database commit error"
      }
    }
  }
}

