{
  "type": "statechart",
  "id": "rbac_service_statechart",
  "initial": "idle",
  "context": {
    "settings_service": "SettingsService",
    "user_id": "UUID",
    "action": "PermissionAction",
    "scope": "PermissionScope",
    "scope_id": "UUID | None"
  },
  "states": {
    "idle": {
      "description": "Service ready for permission checks",
      "on": {
        "CHECK_PERMISSION": "checking_admin",
        "ASSIGN_ROLE": "assigning_role",
        "REMOVE_ROLE": "removing_role",
        "GET_ACCESSIBLE_IDS": "fetching_accessible_ids"
      }
    },
    "checking_admin": {
      "entry": "_is_admin",
      "description": "Check if user has Admin role or is_superuser flag",
      "on": {
        "IS_ADMIN": "complete_authorized",
        "NOT_ADMIN": "checking_scope"
      }
    },
    "checking_scope": {
      "entry": "determine_scope_type",
      "description": "Route to flow or project permission check",
      "on": {
        "FLOW_SCOPE": "checking_flow_permission",
        "PROJECT_SCOPE": "checking_project_permission",
        "INVALID_SCOPE": "complete_denied"
      }
    },
    "checking_flow_permission": {
      "entry": "_can_access_flow",
      "description": "Check flow-level permission with project inheritance",
      "on": {
        "HAS_PERMISSION": "complete_authorized",
        "NO_PERMISSION": "complete_denied"
      }
    },
    "checking_project_permission": {
      "entry": "_can_access_project",
      "description": "Check project-level permission",
      "on": {
        "HAS_PERMISSION": "complete_authorized",
        "NO_PERMISSION": "complete_denied"
      }
    },
    "assigning_role": {
      "entry": "assign_role",
      "description": "Create UserRoleAssignment with immutability check",
      "on": {
        "ASSIGNED": "complete_success",
        "IMMUTABLE": "error_immutable",
        "ERROR": "error_assignment"
      }
    },
    "removing_role": {
      "entry": "remove_role",
      "description": "Delete UserRoleAssignment if not immutable",
      "on": {
        "REMOVED": "complete_success",
        "IMMUTABLE": "error_immutable",
        "NOT_FOUND": "error_not_found"
      }
    },
    "fetching_accessible_ids": {
      "entry": "get_accessible_scope_ids",
      "description": "Bulk query for accessible flow/project IDs",
      "on": {
        "FETCHED": "complete_success",
        "ERROR": "error_query"
      }
    },
    "complete_authorized": {
      "type": "final",
      "data": {
        "authorized": true
      }
    },
    "complete_denied": {
      "type": "final",
      "data": {
        "authorized": false
      }
    },
    "complete_success": {
      "type": "final",
      "data": {
        "success": true
      }
    },
    "error_immutable": {
      "type": "final",
      "entry": "raise_error",
      "data": {
        "error": "Cannot modify immutable assignment"
      }
    },
    "error_assignment": {
      "type": "final",
      "entry": "raise_error",
      "data": {
        "error": "Assignment failed"
      }
    },
    "error_not_found": {
      "type": "final",
      "entry": "raise_error",
      "data": {
        "error": "Assignment not found"
      }
    },
    "error_query": {
      "type": "final",
      "entry": "raise_error",
      "data": {
        "error": "Query failed"
      }
    }
  }
}

