rawCode.typescript:
export function RBACGuard({
  action,
  scope,
  scopeId,
  children,
  fallback = null,
  loadingFallback,
  showDisabled = false,
}: RBACGuardProps) {
  const { hasPermission, isLoading } = usePermission(action, scope, scopeId);

  if (isLoading) {
    return (
      <>
        {loadingFallback ?? (
          <div className="flex items-center justify-center p-2">
            <CustomLoader remSize={2} />
          </div>
        )}
      </>
    );
  }

  if (!hasPermission) {
    return <>{fallback}</>;
  }

  return <>{children}</>;
}

content.code:
const { userData } = useContext(AuthContext);

const { data, isLoading, error } = useQuery<PermissionCheckResponse>({
  queryKey: ['permission', action, scope, scopeId, userData?.id],
  queryFn: async () => {
    const params = new URLSearchParams({ action, scope });
    if (scopeId) params.append('scope_id', scopeId);
    const response = await api.get<PermissionCheckResponse>(
      `/api/v1/rbac/check-permission?${params.toString()}`
    );
    return response.data;
  },
  enabled: !!userData,
  staleTime: 30000,
  gcTime: 300000,
});

return {
  hasPermission: data?.authorized ?? false,
  isLoading,
  error,
  reason: data?.reason,
};
